                "lowMinutes": 45,
                "likelyMinutes": 60,
                "highMinutes": 90
              },
              "readinessCriterion": "Solves a changed unfamiliar circuit correctly, states why the chosen method's assumptions/topology apply, and does not need assistance."
            }
          ]
        },
