{
  "decision": "REVISE",
  "detail": {
    "days": 14,
    "checkpoint": "A working script that reads a small expenses CSV with csv.DictReader, groups rows by category into totals, and reports malformed rows (wrong field count or non-numeric amount) without crashing, demonstrated on a CSV you supply."
  },
  "plans": [
    {
      "planRef": "plan_1",
      "blueprint": {
        "schemaVersion": 2,
        "strategy": {
          "policy": "ROADMAP",
          "outcome": "Build a small CSV expenses report in Python that groups by category, reports totals, and checks malformed rows. I have never read a CSV in Python.",
          "explanation": "You have never read a CSV in Python, so the useful next checkpoint is a single small working script that covers the whole requested outcome at beginner scale: read the file with csv.DictReader, accumulate per-category totals, and detect malformed rows. One integrated build-and-check activity is enough to reach that checkpoint; splitting reading, grouping and validation into separate activities would add no distinct evidence. Later engineering (larger files, richer validation, packaging, tests) stays strategic and unbooked until this checkpoint works and you ask to expand.",
          "recommendedEffort": {
            "lowMinutes": 45,
            "likelyMinutes": 75,
            "highMinutes": 120
          },
          "phases": [
            {
              "localId": "phase_checkpoint",
              "title": "Working beginner expenses report",
              "outcome": "A runnable script that reads a small expenses CSV, prints per-category totals, and reports malformed rows without crashing.",
              "effort": {
                "lowMinutes": 45,
                "likelyMinutes": 75,
                "highMinutes": 120
              },
              "readinessCriterion": "On a CSV you supply, the script prints correct per-category totals and lists each malformed row with a reason, and you can explain how csv.DictReader and the grouping loop produce those results."
            }
          ]
        },
        "scope": [
          {
            "scopeRef": "scope_1",
            "disposition": "INCLUDED",
            "contribution": "Reading the expenses file with csv.DictReader and accessing fields by column name."
          },
          {
            "scopeRef": "scope_2",
            "disposition": "INCLUDED",
            "contribution": "Accumulating per-category totals in a dictionary and printing them."
          },
          {
            "scopeRef": "scope_3",
            "disposition": "INCLUDED",
            "contribution": "Detecting rows with the wrong number of fields or a non-numeric amount and reporting them instead of crashing."
          },
          {
            "scopeRef": "scope_4",
            "disposition": "INCLUDED",
            "contribution": "The single runnable script that ties reading, grouping and malformed-row reporting into the requested report."
          }
        ],
        "activities": [
          {
            "localId": "build_report",
            "outcomeRefs": [
              "phase_checkpoint"
            ],
            "scopeRefs": [
              "scope_1",
              "scope_2",
              "scope_3",
              "scope_4"
            ],
            "title": "Build and check a beginner CSV expenses report",
            "activityType": "Guided build with independent check",
            "purpose": "Reach the checkpoint by writing one small script that reads a CSV, groups totals by category, and reports malformed rows, then verifying it on your own data.",
            "instructions": "1) Create a small expenses CSV with columns date,category,amount and 6-10 rows, including at least one row with a missing field and one row with a non-numeric amount. 2) Write a Python script that opens the file with open(...) and csv.DictReader, and prints each row's category and amount to confirm the reading works. 3) Add a dictionary that accumulates amount per category, converting amount with float() inside a try/except; on failure, record the row as malformed with the reason 'non-numeric amount'. 4) Also treat rows whose field count differs from the header as malformed with the reason 'wrong field count'. 5) After the loop, print each category with its total, then print each malformed row with its reason. 6) Run the script on your CSV and check that the totals match what you compute by hand and that both malformed rows are reported. 7) Fix any mismatch, then explain in your own words how DictReader gives you fields by name and how the grouping loop builds the totals.",
            "completionCriterion": "The script runs without crashing on your CSV, prints per-category totals that match a hand calculation, lists each malformed row with a reason, and you can explain how csv.DictReader and the grouping loop produce the output.",
            "effort": {
              "lowMinutes": 45,
              "likelyMinutes": 75,
              "highMinutes": 120
            },
            "timeboxMinutes": 90,
            "commitment": {
              "category": "COMMITTED"
            },
            "hardDependencies": [],
            "splitPoints": [
              {
                "afterMinutes": 40,
                "completionCriterion": "The script reads the CSV with csv.DictReader and prints each row's category and amount correctly."
              }
            ]
          }
        ],
        "decisions": {
          "assumptions": [
            "You have basic Python syntax (variables, loops, dictionaries, try/except) available; if not, the first part of the activity will surface that and the checkpoint can be paused for a short prerequisite."
          ],
          "tradeOffs": [
            "Only the beginner checkpoint is booked; larger files, richer validation, tests and packaging are deliberately left unbooked so the first working script is not crowded out."
          ],
          "unresolvedUncertainty": [
            "Your exact Python level beyond 'never read a CSV in Python' is unknown; the activity starts with a short reading step so any gap appears early."
          ],
          "stoppingConditions": [
            "Stop once the script meets the completion criterion on your CSV; do not add extra features or a second validation pass unless the checkpoint fails."
          ]
        }
      }
    }
  ],
  "sharedDependencies": [],
  "tradeOffExplanation": "This books one integrated beginner activity (about 45-120 minutes, timeboxed at 90 with a genuine mid-point split) instead of separate reading, grouping and validation activities, because one working script already produces the evidence the checkpoint needs. Later project milestones remain strategic and unbooked; they will need fresh evidence and an explicit request to expand."
}

